package com.srenterprises.service;
import com.srenterprises.dto.OrderDtos.*; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.math.*; import java.security.*; import java.time.*; import java.util.*;
@Service public class OrderService { final OrderRepository orders; final ProductRepository products; final InventoryRepository inventory; final InventoryTransactionRepository transactions; final UserRepository users; final AuditService audit; public OrderService(OrderRepository o,ProductRepository p,InventoryRepository i,InventoryTransactionRepository t,UserRepository u,AuditService a){orders=o;products=p;inventory=i;transactions=t;users=u;audit=a;} @Transactional public CustomerOrder create(String email,Create request){User customer=users.findByEmailIgnoreCase(email).orElseThrow(); CustomerOrder order=new CustomerOrder();order.customer=customer;order.orderNumber="SRE-"+Instant.now().toEpochMilli()+"-"+Integer.toHexString(new SecureRandom().nextInt(65536));order.recipientName=request.recipientName();order.email=request.email();order.phone=request.phone();order.addressLine=request.addressLine();order.city=request.city();order.state=request.state();order.postalCode=request.postalCode(); BigDecimal subtotal=BigDecimal.ZERO;for(Line line:request.items()){Product product=products.findById(line.productId()).orElseThrow(()->new NoSuchElementException("Product not found"));if(product.status!=ProductStatus.ACTIVE)throw new IllegalArgumentException("Product is unavailable: "+product.name);Inventory stock=inventory.lockByProductId(product.id).orElseThrow(()->new IllegalArgumentException("Inventory is unavailable"));if(stock.quantity<line.quantity())throw new IllegalArgumentException("Insufficient stock for "+product.name);int previous=stock.quantity;stock.quantity-=line.quantity();inventory.save(stock);InventoryTransaction tx=new InventoryTransaction();tx.product=product;tx.actor=customer;tx.previousQuantity=previous;tx.changeQuantity=-line.quantity();tx.newQuantity=stock.quantity;tx.reason="Order "+order.orderNumber;transactions.save(tx);BigDecimal price=product.discountPrice==null?product.price:product.discountPrice;OrderItem item=new OrderItem();item.order=order;item.product=product;item.productName=product.name;item.sku=product.sku;item.unitPrice=price;item.quantity=line.quantity();item.lineTotal=price.multiply(BigDecimal.valueOf(line.quantity()));order.items.add(item);subtotal=subtotal.add(item.lineTotal);}order.subtotal=subtotal;order.total=subtotal;orders.save(order);audit.record("ORDER_CREATED","ORDER",order.id,"Created order "+order.orderNumber);return order;} @Transactional public CustomerOrder status(UUID id,OrderStatus status){CustomerOrder o=orders.findById(id).orElseThrow(()->new NoSuchElementException("Order not found"));o.status=status;o.updatedAt=Instant.now();orders.save(o);audit.record("ORDER_STATUS_CHANGED","ORDER",id,"Changed "+o.orderNumber+" to "+status);return o;} }
